var o=[{title:`Semana uno: aprende la rutina`,text:`Elige dos sesiones cortas de cuerpo completo y da paseos suaves los demás días si te apetece. Practica los patrones básicos de sentadilla, bisagra, empuje, tracción y core con movimientos que se ajusten a tu equipamiento y a tu cuerpo. Una primera sesión podría ser de una o dos series de varios ejercicios.`},{title:`Semanas dos a cuatro: repite y observa`,text:`Mantén los mismos ejercicios y después añade poco a poco repeticiones, un poco de carga o una serie extra si te estás recuperando bien. Los pequeños aumentos que puedes mantener te ayudan a ganar confianza. No interpretes cada sensación nueva ni cada agujeta como un motivo para cambiar todo el plan.`},{title:`Ejemplo`,text:`El lunes y el jueves, haz sentadillas con silla controladas, remos con apoyo, flexiones en la pared y una retención corta de core. Añade un paseo cómodo otro día. Si un movimiento es demasiado difícil, elige una versión más fácil. Si es muy fácil, hazlo más difícil poco a poco manteniendo el control.`},{title:`Qué esperar al principio`,text:`Las primeras ganancias de fuerza suelen venir de una mejor habilidad y de una mejor coordinación entre los nervios y los músculos, y los cambios físicos se notan más con el tiempo. Faltar a un entrenamiento no borra tu progreso. Simplemente retómalo en la siguiente sesión prevista.`},{title:`Cómo usar TrainUp`,text:`Indica con sinceridad tu nivel de forma física en Perfil, junto con el equipamiento que tienes y la duración de tu sesión. Después de cada entrenamiento, valora tu esfuerzo (RPE). Tu plan solo cambia cuando lo generas de nuevo, y nunca a partir de menos de 3 entrenamientos. Si tus últimos 4 fueron fáciles (RPE 5 o menos) y completos, el siguiente plan sube un paso.`}];var s=[{label:`Guía práctica del ACSM de 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS: caminar por la salud`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`}];var n={sections:o,sources:s};export{n as default,o as sections,s as sources};